<script setup>import {Link} from '@inertiajs/vue3';import Button from '@/Components/UI/Button.vue';import Icon from '@/Components/UI/Icon.vue';import FormError from '@/Components/UI/FormError.vue';import ValidationErrorSummary from '@/Components/UI/ValidationErrorSummary.vue';defineProps({form:Object,employees:[Array,Object],departments:[Array,Object],cancelHref:String,submitLabel:String});defineEmits(['submit']);const cls='block h-10 w-full rounded-lg border border-gray-200 bg-white px-3 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white';</script>
<template><form class="space-y-5" @submit.prevent="$emit('submit')"><ValidationErrorSummary :errors="form.errors"/><section class="rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-900 dark:bg-gray-950"><header class="border-b border-gray-200 bg-gray-50/70 px-5 py-4 dark:border-gray-900 dark:bg-gray-1000/40"><h2 class="font-bold text-slate-800 dark:text-white">Créneau de planning</h2><p class="mt-1 text-xs text-slate-500">Le planning décrit une affectation ; aucune règle de chevauchement n’est inventée.</p></header><div class="grid gap-4 p-5 sm:grid-cols-2"><div><label class="mb-1.5 block text-sm font-medium">Employé *</label><select v-model="form.employee_uuid" :class="cls" required><option value="">Sélectionner</option><option v-for="item in employees" :key="item.uuid" :value="item.uuid">{{item.employee_number}} · {{item.name}}</option></select><FormError v-if="form.errors.employee_uuid">{{form.errors.employee_uuid}}</FormError></div><div><label class="mb-1.5 block text-sm font-medium">Département</label><select v-model="form.department_uuid" :class="cls"><option value="">Département de l’employé</option><option v-for="item in departments" :key="item.uuid" :value="item.uuid">{{item.label}}</option></select><FormError v-if="form.errors.department_uuid">{{form.errors.department_uuid}}</FormError></div><div><label class="mb-1.5 block text-sm font-medium">Début *</label><input v-model="form.starts_at" type="datetime-local" :class="cls" required><FormError v-if="form.errors.starts_at">{{form.errors.starts_at}}</FormError></div><div><label class="mb-1.5 block text-sm font-medium">Fin *</label><input v-model="form.ends_at" type="datetime-local" :class="cls" required><FormError v-if="form.errors.ends_at">{{form.errors.ends_at}}</FormError></div><div class="sm:col-span-2"><label class="mb-1.5 block text-sm font-medium">Objet du créneau</label><input v-model="form.title" :class="cls" placeholder="Ex. Garde, permanence, réunion"><FormError v-if="form.errors.title">{{form.errors.title}}</FormError></div><div class="sm:col-span-2"><label class="mb-1.5 block text-sm font-medium">Observation</label><textarea v-model="form.observation" rows="4" class="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white"/><FormError v-if="form.errors.observation">{{form.errors.observation}}</FormError></div></div></section><div class="flex justify-end gap-2"><Button :as="Link" :href="cancelHref" size="rg" variant="white-outline">Annuler</Button><Button size="rg" :disabled="form.processing"><Icon name="check"/><span class="ms-2">{{submitLabel}}</span></Button></div></form></template>
